def kv_cache_gb(num_layers: int, num_heads: int, head_dim: int, seq_len: int, bytes_per_value: int) -> float:
    """KV cache size in GB: 2 x layers x heads x head_dim x seq_len x bytes_per_value."""
    total_bytes = 2 * num_layers * num_heads * head_dim * seq_len * bytes_per_value
    return round(total_bytes / 1e9, 2)

print(kv_cache_gb(32, 32, 128, 4096, 2))
